# Load grids to track demos
import os, re

def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        print("No RLM_SESSION_DIR found")
        return {}

    session_path = os.path.normpath(session_dir + '/../../sessions/')
    basename = os.path.basename(session_dir)
    jsonl_path = session_path + basename + '.jsonl'

    if not os.path.exists(jsonl_path):
        print(f"Session file not found: {jsonl_path}")
        return {}

    G = {}
    with open(jsonl_path) as f:
        content = f.read()

    # Find demo pairs
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, content):
        key = m[1]
        h, w = int(m[2]), int(m[3])
        rows = [r.split() for r in content[m.end():].split('\n')[:h]]
        if key not in G:
            if all(len(r) == w and all(c.isdigit() for c in r) for r in rows):
                G[key] = [[int(c) for c in r] for r in rows]

    return G

G = load_grids()
print("Loaded grids:")
for k, v in G.items():
